function [hd] = cmg_rate(h, h0, k_speed, torque_max)
%CMG_RATE  The CMG rotor's momentum rate [N m]: -k_speed (h - h0), within its largest torque.
%   h: real[1] (passed a plain number)
%   h0: real[1] (passed a plain number)
%   k_speed: real[1] (passed a plain number)
%   torque_max: real[1] (passed a plain number)
%   returns hd: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    hd = 0;
    hd = asils.models.coilsat.act_clamp(((-(k_speed)) * (h - h0)), (-(torque_max)), torque_max);
end
